import WidgetKit
import SwiftUI

struct FlamioEntry: TimelineEntry { let date: Date; let snapshot: WidgetSnapshot }
struct FlamioProvider: TimelineProvider {
    func placeholder(in context: Context) -> FlamioEntry { FlamioEntry(date: .now, snapshot: WidgetSnapshot()) }
    func getSnapshot(in context: Context, completion: @escaping (FlamioEntry) -> Void) { completion(FlamioEntry(date: .now, snapshot: read())) }
    func getTimeline(in context: Context, completion: @escaping (Timeline<FlamioEntry>) -> Void) { let now = Date.now; let entry = FlamioEntry(date: now, snapshot: read()); let next = Calendar.current.date(byAdding: .minute, value: 30, to: now) ?? now.addingTimeInterval(1800); completion(Timeline(entries: [entry], policy: .after(next))) }
    private func read() -> WidgetSnapshot { guard let d = UserDefaults(suiteName: FlamioShared.appGroup)?.data(forKey: FlamioShared.widgetSnapshotKey), let s = try? JSONDecoder().decode(WidgetSnapshot.self, from: d) else { return WidgetSnapshot() }; return s }
}
struct FlamioWidgetView: View { @Environment(\.widgetFamily) var family; let entry: FlamioEntry; var body: some View { ZStack { LinearGradient(colors: [Color(red: 0.04, green: 0.01, blue: 0.12), Color.purple.opacity(0.55)], startPoint: .topLeading, endPoint: .bottomTrailing); switch family { case .systemSmall: SmallWidget(snapshot: entry.snapshot); case .systemMedium: MediumWidget(snapshot: entry.snapshot); default: LargeWidget(snapshot: entry.snapshot) } }.containerBackground(for: .widget) { Color.black } } }
struct SmallWidget: View { let snapshot: WidgetSnapshot; var body: some View { VStack(alignment: .leading, spacing: 8) { Text("🔥").font(.title2); Text(snapshot.petName).font(.headline); Text("\(snapshot.streak) дней").font(.title3.bold()); Spacer(); Label("\(snapshot.weatherTemperature)°", systemImage: snapshot.weatherSymbol).font(.caption); Text(snapshot.weatherCity).font(.caption2).foregroundStyle(.secondary) }.padding() } }
struct MediumWidget: View { let snapshot: WidgetSnapshot; var body: some View { HStack { VStack(alignment: .leading) { Text("🔥 \(snapshot.petName)").font(.headline); Text("\(snapshot.streak) дней подряд").font(.caption).foregroundStyle(.orange); Spacer(); Label("\(snapshot.weatherTemperature)° · \(snapshot.weatherCity)", systemImage: snapshot.weatherSymbol).font(.caption) }; Spacer(); VStack(alignment: .trailing) { Text("Смены").font(.caption).foregroundStyle(.secondary); Text("\(snapshot.shiftHours, specifier: "%.1f") ч").font(.title2.bold()); Text("Доход \(Int(snapshot.monthIncome)) \(snapshot.currency)").font(.caption).foregroundStyle(.green) } }.padding() } }
struct LargeWidget: View { let snapshot: WidgetSnapshot; var body: some View { VStack(alignment: .leading, spacing: 10) { HStack { Text("Flamio").font(.title2.bold()); Spacer(); Text("\(snapshot.weatherTemperature)°").font(.title.bold()) }; Text("\(snapshot.weatherCity) · огонёк \(snapshot.streak) дней").font(.caption).foregroundStyle(.secondary); Divider(); HStack { WidgetStat(label: "Часы", value: String(format: "%.1f", snapshot.shiftHours)); WidgetStat(label: "Доход", value: "\(Int(snapshot.monthIncome))\(snapshot.currency)"); WidgetStat(label: "Траты", value: "\(Int(snapshot.monthSpending))\(snapshot.currency)") }; Spacer(); Text("Обновлено автоматически · \(snapshot.updatedAt.formatted(.dateTime.hour().minute()))").font(.caption2).foregroundStyle(.secondary) }.padding() } }
struct WidgetStat: View { let label: String; let value: String; var body: some View { VStack(alignment: .leading) { Text(label).font(.caption2).foregroundStyle(.secondary); Text(value).font(.headline) }.frame(maxWidth: .infinity, alignment: .leading) } }
@main struct FlamioWidget: Widget { let kind = "FlamioWidget"; var body: some WidgetConfiguration { StaticConfiguration(kind: kind, provider: FlamioProvider()) { entry in FlamioWidgetView(entry: entry) }.configurationDisplayName("Flamio").description("Погода, смены, питомец и деньги").supportedFamilies([.systemSmall, .systemMedium, .systemLarge, .systemExtraLarge]) } }
